<?php
/* خطیار — شکایات تاکسیرانان */
function _complaints_settings(){
  $r=Db::one("SELECT value FROM app_settings WHERE key='complaints_settings'");
  $v=$r?json_decode($r['value'],true):[]; return is_array($v)?$v:[];
}
function _complaints_can($u,$kind='submit'){
  $s=_complaints_settings();
  if((int)($u['is_admin']??0) || (int)($u['level']??99)<=3) return true;
  if(in_array((int)$u['id'],array_map('intval',$s['allowed_user_ids']??[]),true) || in_array((int)$u['role_id'],array_map('intval',$s['allowed_role_ids']??[]),true)) return true;
  if($kind==='receive' && (int)$u['id']===(int)($s['receiver_user_id']??0)) return true;
  if($kind==='manage' && (int)$u['id']===(int)($s['manager_user_id']??0)) return true;
  return false;
}
function _complaints_require($u,$kind='submit'){if(!_complaints_can($u,$kind)) Http::error('دسترسی به بخش شکایات برای شما فعال نیست.',403);}
function _complaints_tables(){
  // Schema is installed only by php/migrations/2026_10_05_complaints.sql.
  // Never CREATE/ALTER tables during an API request: this avoids locks, races and latency.
}
function _complaint_code(){return 'SHK-'.date('YmdHis').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8));}
function _complaint_driver($id){return Db::one("SELECT d.*,v.id vehicle_id,v.plate,v.line_id,v.operating_code vehicle_operating_code,l.code line_code,l.origin line_origin FROM drivers d LEFT JOIN vehicle_drivers vd ON vd.driver_id=d.id LEFT JOIN vehicles v ON v.id=vd.vehicle_id LEFT JOIN lines l ON l.id=v.line_id WHERE d.id=? LIMIT 1",[$id]);}

route('GET','/api/complaints/access',function($p,$b,$u){_complaints_tables();$s=_complaints_settings();return ['allowed'=>_complaints_can($u),'can_submit'=>_complaints_can($u),'can_receive'=>_complaints_can($u,'receive'),'can_manage'=>_complaints_can($u,'manage'),'receiver_user_id'=>$s['receiver_user_id']??null,'manager_user_id'=>$s['manager_user_id']??null];});
route('GET','/api/complaints/drivers',function($p,$b,$u){_complaints_tables();_complaints_require($u);$q=trim((string)($_GET['q']??''));if($q==='')return[];$like='%'.$q.'%';return Db::all("SELECT DISTINCT d.id,d.national_id,d.first_name,d.last_name,d.mobile,d.operating_code,v.id vehicle_id,v.plate,v.operating_code vehicle_operating_code,v.line_id,l.code line_code,l.origin line_origin,vd.line_code_in_line FROM drivers d LEFT JOIN vehicle_drivers vd ON vd.driver_id=d.id LEFT JOIN vehicles v ON v.id=vd.vehicle_id LEFT JOIN lines l ON l.id=v.line_id WHERE d.national_id LIKE ? OR v.plate LIKE ? OR l.code LIKE ? OR d.operating_code LIKE ? OR v.operating_code LIKE ? OR vd.line_code_in_line LIKE ? ORDER BY d.last_name,d.first_name LIMIT 50",[$like,$like,$like,$like,$like,$like]);});
route('GET','/api/complaints/default-location',function($p,$b,$u){_complaints_require($u);try{$r=Db::one("SELECT in_lat lat,in_lng lng,in_station name,check_in at FROM staff_attendance WHERE user_id=? ORDER BY id DESC LIMIT 1",[$u['id']]);if($r&&$r['lat']!==null)return $r;}catch(Throwable $e){}try{$r=Db::one("SELECT lat,lng,created_at at FROM attendances WHERE user_id=? ORDER BY id DESC LIMIT 1",[$u['id']]);if($r)return $r;}catch(Throwable $e){}return null;});
route('GET','/api/complaints/cities',function($p,$b,$u){_complaints_require($u);try{return Db::all("SELECT DISTINCT name FROM iran_cities ORDER BY name");}catch(Throwable $e){return [];}});
route('GET','/api/complaints/categories',function($p,$b,$u){_complaints_require($u);_complaints_tables();$t=(string)($_GET['type']??'');return Db::all("SELECT * FROM complaint_categories WHERE is_active=1 AND (?='' OR complaint_type=?) ORDER BY complaint_type,sort_order,id",[$t,$t]);});
route('GET','/api/complaints/my',function($p,$b,$u){if(!_complaints_can($u,'receive')&&!_complaints_can($u,'manage'))Http::error('دسترسی به کارتابل شکایات برای شما فعال نیست.',403);return Db::all("SELECT c.*,CONCAT(d.first_name,' ',d.last_name) driver_name,d.national_id,v.plate,l.code line_code FROM complaints c JOIN drivers d ON d.id=c.driver_id LEFT JOIN vehicles v ON v.id=c.vehicle_id LEFT JOIN lines l ON l.id=c.line_id WHERE c.assigned_to=? ORDER BY c.created_at DESC LIMIT 300",[$u['id']]);});
route('GET','/api/complaints/reviewed',function($p,$b,$u){if(!_complaints_can($u,'receive')&&!_complaints_can($u,'manage'))Http::error('دسترسی به شکایات بررسی‌شده برای شما فعال نیست.',403);return Db::all("SELECT DISTINCT c.*,CONCAT(d.first_name,' ',d.last_name) driver_name,d.national_id,v.plate,l.code line_code FROM complaints c JOIN drivers d ON d.id=c.driver_id LEFT JOIN vehicles v ON v.id=c.vehicle_id LEFT JOIN lines l ON l.id=c.line_id JOIN complaint_workflow w ON w.complaint_id=c.id WHERE w.actor_id=? ORDER BY c.updated_at DESC LIMIT 300",[$u['id']]);});
route('GET','/api/complaints/driver/{id}',function($p,$b,$u){if(!_complaints_can($u,'submit')&&!_complaints_can($u,'receive')&&!_complaints_can($u,'manage'))Http::error('دسترسی به سوابق شکایت این تاکسیران برای شما فعال نیست.',403);$rows=Db::all("SELECT c.*,CONCAT(d.first_name,' ',d.last_name) driver_name,d.national_id,v.plate,l.code line_code FROM complaints c JOIN drivers d ON d.id=c.driver_id LEFT JOIN vehicles v ON v.id=c.vehicle_id LEFT JOIN lines l ON l.id=c.line_id WHERE c.driver_id=? ORDER BY c.created_at DESC",[(int)$p['id']]);foreach($rows as &$r)$r['workflow']=Db::all("SELECT w.*,CONCAT(u.first_name,' ',u.last_name) actor_name,CONCAT(t.first_name,' ',t.last_name) target_name FROM complaint_workflow w JOIN users u ON u.id=w.actor_id LEFT JOIN users t ON t.id=w.to_user_id WHERE w.complaint_id=? ORDER BY w.created_at",[$r['id']]);return $rows;});
route('GET','/api/complaints/{id}',function($p,$b,$u){_complaints_require($u);$c=Db::one("SELECT c.*,CONCAT(d.first_name,' ',d.last_name) driver_name,d.national_id,v.plate,l.code line_code FROM complaints c JOIN drivers d ON d.id=c.driver_id LEFT JOIN vehicles v ON v.id=c.vehicle_id LEFT JOIN lines l ON l.id=c.line_id WHERE c.id=?",[(int)$p['id']]);if(!$c)Http::error('شکایت یافت نشد',404);$c['workflow']=Db::all("SELECT w.*,CONCAT(u.first_name,' ',u.last_name) actor_name,CONCAT(t.first_name,' ',t.last_name) target_name FROM complaint_workflow w JOIN users u ON u.id=w.actor_id LEFT JOIN users t ON t.id=w.to_user_id WHERE w.complaint_id=? ORDER BY w.created_at",[$c['id']]);return $c;});
route('POST','/api/complaints',function($p,$b,$u){_complaints_require($u);_complaints_tables();$driver=_complaint_driver((int)($b['driver_id']??0));if(!$driver)Http::error('تاکسیران یافت نشد',404);foreach(['complainant_first_name','complainant_last_name','complainant_mobile','complainant_type','complaint_type','subject','body'] as $k)if(trim((string)($b[$k]??''))==='')Http::error('اطلاعات شکایت کامل نیست',422);$s=_complaints_settings();$receiver=(int)($s['receiver_user_id']??0);if(!$receiver)Http::error('کاربر دریافت شکایات در تنظیمات تعیین نشده است',422);$code=_complaint_code();$lineId=(int)($b['line_id']??$driver['line_id']??0);$id=Db::insert("INSERT INTO complaints(tracking_code,driver_id,vehicle_id,line_id,received_by,receive_lat,receive_lng,complainant_first_name,complainant_last_name,complainant_mobile,complainant_type,receipt_channel,stay_days,residence_city,complaint_type,category_id,subject,body,signature_data,status,assigned_to,manager_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$code,$driver['id'],$driver['vehicle_id']??null,$lineId?:null,$u['id'],$b['lat']??null,$b['lng']??null,$b['complainant_first_name'],$b['complainant_last_name'],$b['complainant_mobile'],$b['complainant_type'],isset($b['stay_days'])?(int)$b['stay_days']:null,$b['residence_city']??null,$b['complaint_type'],(int)($b['category_id']??0)?:null,$b['subject'],$b['body'],$b['signature_data'],'received',$receiver,(int)($s['manager_user_id']??0)?:null]);Db::insert("INSERT INTO complaint_workflow(complaint_id,actor_id,action,to_user_id,note) VALUES(?,?,?,?,?)",[$id,$u['id'],'received',$receiver,'ثبت اولیه شکایت']);try{Db::run("INSERT INTO notifications(user_id,title,body,data) VALUES(?,?,?,?)",[$receiver,'شکایت جدید','یک شکایت جدید برای بررسی به شما ارجاع شد.',json_encode(['type'=>'complaint','complaint_id'=>$id,'tracking_code'=>$code],JSON_UNESCAPED_UNICODE)]);}catch(Throwable $e){}try{if(!empty($s['sms_enabled']))Sms::send([$b['complainant_mobile']],str_replace('{tracking_code}',$code,$s['sms_template']??''),'complaint',$u['id']);}catch(Throwable $e){}return ['ok'=>true,'id'=>$id,'tracking_code'=>$code,'assigned_to'=>$receiver];});
route('POST','/api/complaints/{id}/action',function($p,$b,$u){$id=(int)$p['id'];$c=Db::one("SELECT * FROM complaints WHERE id=? LIMIT 1",[$id]);if(!$c)Http::error('شکایت یافت نشد',404);$isManager=_complaints_can($u,'manage');$isReceiver=_complaints_can($u,'receive');$isAssigned=(int)($c['assigned_to']??0)===(int)$u['id'];if(!$isManager&&!$isReceiver&&!$isAssigned)Http::error('شما مجاز به بررسی این شکایت نیستید.',403);$act=(string)($b['action']??'');$note=trim((string)($b['note']??''));if(!in_array($act,['note','forward','manager_forward','back','close','reply'],true))Http::error('عملیات نامعتبر',422);if($act==='manager_forward'&&!$isReceiver)Http::error('فقط دریافت‌کننده می‌تواند شکایت را به مسئول رسیدگی ارجاع دهد.',403);if(in_array($act,['back','reply'],true)&&!$isManager)Http::error('این عملیات فقط توسط مسئول رسیدگی انجام می‌شود.',403);$s=_complaints_settings();$manager=(int)($s['manager_user_id']??0);$receiver=(int)($s['receiver_user_id']??0);if($act==='manager_forward'&&!$manager)Http::error('مسئول رسیدگی در تنظیمات تعیین نشده است.',422);if(in_array($act,['back','reply'],true)&&!$receiver)Http::error('دریافت‌کننده شکایات در تنظیمات تعیین نشده است.',422);$target=(int)($b['to_user_id']??0)?:null;$status=$c['status'];$closedAt=null;$closedBy=null;if($act==='close'){$status='closed';$target=null;$closedAt=date('Y-m-d H:i:s');$closedBy=$u['id'];}elseif($act==='forward'){$status='in_review';$target=$receiver?:$target;}elseif($act==='manager_forward'){$status='manager_review';$target=$manager;}elseif($act==='back'){$status='received';$target=$receiver;}elseif($act==='reply'){$status='answered';$target=$receiver;}elseif($act==='note'){$target=$c['assigned_to']?:null;}Db::run("UPDATE complaints SET status=?,assigned_to=?,closed_at=?,closed_by=?,updated_at=NOW() WHERE id=?",[$status,$target,$closedAt,$closedBy,$id]);Db::insert("INSERT INTO complaint_workflow(complaint_id,actor_id,action,to_user_id,note) VALUES(?,?,?,?,?)",[$id,$u['id'],$act,$target,$note?:null]);try{if($target&&(int)$target!==(int)$u['id'])Db::run("INSERT INTO notifications(user_id,title,body,data) VALUES(?,?,?,?)",[$target,'ارجاع شکایت','یک شکایت برای بررسی به شما ارجاع شد.',json_encode(['type'=>'complaint','complaint_id'=>$id],JSON_UNESCAPED_UNICODE)]);}catch(Throwable $e){}return ['ok'=>true,'status'=>$status,'assigned_to'=>$target];});
route('GET','/api/admin/complaints/channel-stats',function($p,$b,$u){_complaints_admin($u);$r=Db::all("SELECT receipt_channel channel,COUNT(*) count FROM complaints GROUP BY receipt_channel");$out=['software'=>0,'phone'=>0,'in_person'=>0];foreach($r as $x){$k=(string)$x['channel'];if(array_key_exists($k,$out))$out[$k]=(int)$x['count'];}$total=array_sum($out);return ['total'=>$total,'items'=>[['channel'=>'software','title'=>'کاربران نرم‌افزار','count'=>$out['software'],'percent'=>$total?round($out['software']*100/$total,1):0],['channel'=>'phone','title'=>'تماس تلفنی','count'=>$out['phone'],'percent'=>$total?round($out['phone']*100/$total,1):0],['channel'=>'in_person','title'=>'حضوری','count'=>$out['in_person'],'percent'=>$total?round($out['in_person']*100/$total,1):0]]];});
route('GET','/api/admin/complaints/dashboard',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);$total=(int)(Db::one("SELECT COUNT(*) n FROM complaints")['n']??0);$closed=(int)(Db::one("SELECT COUNT(*) n FROM complaints WHERE status='closed'")['n']??0);$open=$total-$closed;$byLine=Db::all("SELECT COALESCE(l.code,'بدون خط') line_code,COUNT(*) n FROM complaints c LEFT JOIN lines l ON l.id=c.line_id GROUP BY c.line_id,l.code ORDER BY n DESC LIMIT 10");return ['total'=>$total,'closed'=>$closed,'open'=>$open,'in_progress'=>$open,'by_line'=>$byLine];});
route('GET','/api/admin/complaints/report',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);$w=['1=1'];$a=[];$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$line=(int)($_GET['line_id']??0);$driver=(int)($_GET['driver_id']??0);if($from){$w[]='c.created_at>=?';$a[]=$from.' 00:00:00';}if($to){$w[]='c.created_at<=?';$a[]=$to.' 23:59:59';}if($line){$w[]='c.line_id=?';$a[]=$line;}if($driver){$w[]='c.driver_id=?';$a[]=$driver;}return Db::all("SELECT c.tracking_code,c.created_at,c.status,c.complaint_type,cc.title category,c.subject,CONCAT(c.complainant_first_name,' ',c.complainant_last_name) complainant,c.complainant_mobile,CONCAT(d.first_name,' ',d.last_name) driver_name,d.national_id,v.plate,l.code line_code FROM complaints c JOIN drivers d ON d.id=c.driver_id LEFT JOIN complaint_categories cc ON cc.id=c.category_id LEFT JOIN vehicles v ON v.id=c.vehicle_id LEFT JOIN lines l ON l.id=c.line_id WHERE ".implode(' AND ',$w)." ORDER BY c.created_at DESC LIMIT 5000",$a);});
route('GET','/api/admin/complaints/settings',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);_complaints_tables();return _complaints_settings();});
route('PUT','/api/admin/complaints/settings',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);_complaints_tables();Db::run("INSERT INTO app_settings(key,value) VALUES('complaints_settings',?) ON DUPLICATE KEY UPDATE value=VALUES(value),updated_at=NOW()",[json_encode($b,JSON_UNESCAPED_UNICODE)]);return ['ok'=>true];});
route('GET','/api/admin/complaints/categories',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);_complaints_tables();return Db::all("SELECT * FROM complaint_categories ORDER BY complaint_type,sort_order,id");});
route('POST','/api/admin/complaints/categories',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);_complaints_tables();Db::insert("INSERT INTO complaint_categories(complaint_type,title,sort_order,is_active) VALUES(?,?,?,1)",[$b['complaint_type'],$b['title'],(int)($b['sort_order']??0)]);return ['ok'=>true];});
route('PUT','/api/admin/complaints/categories/{id}',function($p,$b,$u){if(empty($u['is_admin'])&&(int)($u['level']??99)>3)Http::error('دسترسی مدیریتی لازم است',403);_complaints_tables();Db::run("UPDATE complaint_categories SET title=?,complaint_type=?,sort_order=?,is_active=? WHERE id=?",[$b['title'],$b['complaint_type'],(int)($b['sort_order']??0),!empty($b['is_active'])?1:0,(int)$p['id']]);return ['ok'=>true];});
